"""Bounded incremental loader for stream_alert_denoise JSONL output."""

import datetime
import hashlib
import json
import os
import re
import sys
import time

from flocks.config import Config


IS_WINDOWS = sys.platform == 'win32'
if IS_WINDOWS:
    import msvcrt  # noqa: F401
else:
    import fcntl   # noqa: F401

SOURCE_WORKFLOW_NAME = 'stream_alert_denoise'
TRIAGE_WORKFLOW_NAME = 'stream_alert_triage'
DEFAULT_BATCH_MAX_RECORDS = 10
DEFAULT_BATCH_MAX_BYTES = 32 * 1024 * 1024
_READ_CHUNK_BYTES = 64 * 1024
_CURSOR_ANCHOR_BYTES = 4 * 1024
_CURSOR_VERSION = 2
_FILENAME_RE = re.compile(r'^dedup_result_(\d+)\.jsonl$')


def _flocks_root():
    return Config().get_global().data_dir.parent


def _dedup_root():
    return _flocks_root() / 'workspace' / 'workflows' / SOURCE_WORKFLOW_NAME


def _cursor_path():
    return _flocks_root() / 'workspace' / 'workflows' / TRIAGE_WORKFLOW_NAME / '.triage_cursor.json'



def _batch_lease_path():
    state_dir = _flocks_root() / 'workspace' / 'workflows' / TRIAGE_WORKFLOW_NAME
    state_dir.mkdir(parents=True, exist_ok=True)
    return os.fspath(state_dir / '.triage_batch.lock')


def _acquire_batch_lease():
    path = _batch_lease_path()
    fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o600)
    try:
        if IS_WINDOWS:
            if os.fstat(fd).st_size == 0:
                os.write(fd, b'0')
                os.fsync(fd)
            os.lseek(fd, 0, os.SEEK_SET)
            msvcrt.locking(fd, msvcrt.LK_NBLCK, 1)
        else:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError as exc:
        os.close(fd)
        raise RuntimeError('production_batch_lease_busy') from exc

    try:
        token = f'{os.getpid()}-{time.time_ns()}'
        os.ftruncate(fd, 0)
        os.lseek(fd, 0, os.SEEK_SET)
        os.write(fd, token.encode('ascii'))
        os.fsync(fd)
    except BaseException:
        _release_batch_lease(fd)
        raise
    print(f'[load] acquired production batch lease token={token}')
    return fd, token


def _release_batch_lease(fd):
    if type(fd) is not int or fd < 0:
        return
    try:
        if IS_WINDOWS:
            try:
                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
            except OSError:
                pass
        else:
            fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)

def _date_str(input_date):
    if input_date:
        value = str(input_date).strip()
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
            return value
    return datetime.datetime.now().strftime('%Y-%m-%d')


def _positive_int(value, default):
    try:
        if isinstance(value, bool):
            raise ValueError
        if isinstance(value, float) and not value.is_integer():
            raise ValueError
        if isinstance(value, str) and not re.fullmatch(r'\+?\d+', value.strip()):
            raise ValueError
        parsed = int(value)
        if parsed <= 0:
            raise ValueError
        return parsed
    except (TypeError, ValueError, OverflowError):
        return default


def _file_seq(path, fallback):
    match = _FILENAME_RE.fullmatch(os.path.basename(path))
    return int(match.group(1)) if match else fallback


def _explicit_paths(input_paths, input_path):
    requested = []
    if input_paths:
        values = [input_paths] if isinstance(input_paths, str) else input_paths
        for value in values:
            if value:
                requested.append(os.path.expanduser(str(value)))
    if input_path:
        requested.append(os.path.expanduser(str(input_path)))

    seen = set()
    files = []
    missing = 0
    for path in requested:
        if path in seen:
            continue
        seen.add(path)
        if not os.path.isfile(path):
            missing += 1
            print(f'[load] WARNING: explicit file not found, skipping: {path}')
            continue
        files.append({'path': path, 'seq': _file_seq(path, len(files) + 1)})
    return files, len(seen), missing


def _auto_paths(date_str):
    day_dir = _dedup_root() / date_str
    files = []
    invalid_names = 0
    try:
        with os.scandir(day_dir) as entries:
            for entry in entries:
                if (
                    not entry.is_file()
                    or not entry.name.startswith('dedup_result_')
                    or not entry.name.endswith('.jsonl')
                ):
                    continue
                match = _FILENAME_RE.fullmatch(entry.name)
                if not match:
                    invalid_names += 1
                    continue
                files.append({'path': entry.path, 'seq': int(match.group(1))})
    except FileNotFoundError:
        pass
    except OSError as exc:
        print(f'[load] WARNING: failed to scan {day_dir}: {exc}')
    files.sort(key=lambda item: item['seq'])
    print(f'[load] auto-discovered date={date_str} dir={day_dir} files={len(files)} invalid={invalid_names}')
    return files, invalid_names


def _cursor_file_state(path, byte_offset, stream=None):
    owns_stream = stream is None
    if owns_stream:
        stream = open(path, 'rb')
    current_position = stream.tell()
    try:
        stat_result = os.fstat(stream.fileno())
        head_size = min(byte_offset, _CURSOR_ANCHOR_BYTES)
        stream.seek(0)
        head = stream.read(head_size)
        boundary_start = max(0, byte_offset - _CURSOR_ANCHOR_BYTES)
        stream.seek(boundary_start)
        boundary = stream.read(byte_offset - boundary_start)
        if len(head) != head_size or len(boundary) != byte_offset - boundary_start:
            raise OSError('cursor boundary is beyond the current file size')
        return {
            'device_id': int(stat_result.st_dev),
            'file_id': int(stat_result.st_ino),
            'head_hash': hashlib.sha256(head).hexdigest(),
            'boundary_start': boundary_start,
            'boundary_hash': hashlib.sha256(boundary).hexdigest(),
        }
    finally:
        if owns_stream:
            stream.close()
        else:
            stream.seek(current_position)


def _cursor_matches_file(item, cursor, stream=None):
    try:
        state = _cursor_file_state(item['path'], cursor['byte_offset'], stream=stream)
    except OSError as exc:
        print(f'[load] WARNING: cursor file validation failed for {item["path"]}: {exc}')
        return False
    for key in ('device_id', 'file_id', 'head_hash', 'boundary_start', 'boundary_hash'):
        if state[key] != cursor.get(key):
            print(f'[load] WARNING: cursor invalidated by file identity/content change: '
                  f'{item["path"]} field={key}')
            return False
    return True


def _cursor_revision_bytes(raw_bytes):
    return hashlib.sha256(raw_bytes).hexdigest()



def _normalise_cursor(raw_cursor, expected_date=None, explicit=False):
    if not isinstance(raw_cursor, dict):
        return None
    version = raw_cursor.get('version')
    cursor_date = raw_cursor.get('date')
    file_name = raw_cursor.get('file_name')
    file_seq = raw_cursor.get('file_seq')
    byte_offset = raw_cursor.get('byte_offset')
    device_id = raw_cursor.get('device_id')
    file_id = raw_cursor.get('file_id')
    head_hash = raw_cursor.get('head_hash')
    boundary_start = raw_cursor.get('boundary_start')
    boundary_hash = raw_cursor.get('boundary_hash')
    if type(version) is not int or version != _CURSOR_VERSION:
        return None
    if not isinstance(cursor_date, str) or not isinstance(file_name, str):
        return None
    integer_fields = (file_seq, byte_offset, device_id, file_id, boundary_start)
    if any(type(value) is not int for value in integer_fields):
        return None
    if expected_date and cursor_date != expected_date:
        return None
    if (
        not file_name
        or file_seq < 0
        or byte_offset < 0
        or device_id < 0
        or file_id < 0
        or boundary_start < 0
        or boundary_start > byte_offset
        or not isinstance(head_hash, str)
        or not re.fullmatch(r'[0-9a-f]{64}', head_hash)
        or not isinstance(boundary_hash, str)
        or not re.fullmatch(r'[0-9a-f]{64}', boundary_hash)
    ):
        return None

    cursor = {
        'version': _CURSOR_VERSION,
        'date': cursor_date,
        'file_seq': file_seq,
        'file_name': file_name,
        'byte_offset': byte_offset,
        'device_id': device_id,
        'file_id': file_id,
        'head_hash': head_hash,
        'boundary_start': boundary_start,
        'boundary_hash': boundary_hash,
    }
    updated_at = raw_cursor.get('updated_at')
    if isinstance(updated_at, str) and updated_at:
        cursor['updated_at'] = updated_at
    if raw_cursor.get('skipping_oversized_line') is True:
        cursor['skipping_oversized_line'] = True
    if explicit:
        cursor_path = raw_cursor.get('path')
        if isinstance(cursor_path, str) and cursor_path:
            cursor['path'] = os.path.expanduser(cursor_path)
        file_index = raw_cursor.get('file_index')
        if type(file_index) is int and file_index >= 0:
            cursor['file_index'] = file_index
    return cursor



def _load_production_cursor(path, date_str):
    try:
        with open(path, 'rb') as stream:
            raw_bytes = stream.read()
    except FileNotFoundError:
        return None, None
    except Exception as exc:
        print(f'[load] WARNING: failed to read cursor {path}: {exc}; restarting date from first file')
        return None, None

    revision = _cursor_revision_bytes(raw_bytes)
    try:
        raw_cursor = json.loads(raw_bytes.decode('utf-8'))
    except Exception as exc:
        print(f'[load] WARNING: invalid cursor {path}: {exc}; restarting date from first file')
        return None, revision

    cursor = _normalise_cursor(raw_cursor, expected_date=date_str)
    if cursor is None:
        print(f'[load] WARNING: stale, legacy, or malformed cursor {path}; '
              'restarting date from first file')
    return cursor, revision



def _start_position(files, cursor, explicit):
    if not files or cursor is None:
        return 0, 0, False

    index = None
    if explicit:
        cursor_path = cursor.get('path')
        if cursor_path:
            index = next((i for i, item in enumerate(files) if item['path'] == cursor_path), None)
        if index is None:
            requested_index = cursor.get('file_index')
            if isinstance(requested_index, int) and 0 <= requested_index < len(files):
                if os.path.basename(files[requested_index]['path']) == cursor['file_name']:
                    index = requested_index
        if index is None:
            index = next((
                i for i, item in enumerate(files)
                if os.path.basename(item['path']) == cursor['file_name']
            ), None)
        if index is None:
            print('[load] WARNING: replay cursor file is absent; restarting explicit paths from first file')
            return 0, 0, True
    else:
        index = next((
            i for i, item in enumerate(files)
            if os.path.basename(item['path']) == cursor['file_name']
        ), None)
        if index is None:
            index = next((i for i, item in enumerate(files) if item['seq'] > cursor['file_seq']), len(files))
            return index, 0, False

    if not _cursor_matches_file(files[index], cursor):
        return index, 0, True
    return index, cursor['byte_offset'], False



def _cursor_after(
    item,
    file_index,
    date_str,
    byte_offset,
    explicit,
    skipping_oversized_line=False,
    stream=None,
):
    cursor = {
        'version': _CURSOR_VERSION,
        'date': date_str,
        'file_seq': item['seq'],
        'file_name': os.path.basename(item['path']),
        'byte_offset': byte_offset,
        **_cursor_file_state(item['path'], byte_offset, stream=stream),
    }
    if skipping_oversized_line:
        cursor['skipping_oversized_line'] = True
    if explicit:
        cursor['file_index'] = file_index
        cursor['path'] = item['path']
    return cursor


def _read_bounded_line(stream, budget):
    chunks = []
    scanned = 0
    while scanned < budget:
        chunk = stream.readline(min(_READ_CHUNK_BYTES, budget - scanned))
        if not chunk:
            return ('eof' if scanned == 0 else 'partial'), None, scanned
        chunks.append(chunk)
        scanned += len(chunk)
        if chunk.endswith(b'\n'):
            return 'line', b''.join(chunks), scanned
    return 'limit', None, scanned


def _discard_to_newline(stream, budget):
    discarded = 0
    while discarded < budget:
        chunk = stream.readline(min(_READ_CHUNK_BYTES, budget - discarded))
        if not chunk:
            return 'eof', discarded
        discarded += len(chunk)
        if chunk.endswith(b'\n'):
            return 'line', discarded
    return 'limit', discarded


def _cursor_position(files, cursor):
    if cursor is None:
        return None
    cursor_path = cursor.get('path')
    if cursor_path:
        index = next((i for i, item in enumerate(files) if item['path'] == cursor_path), None)
    else:
        index = None
    if index is None:
        index = next((
            i for i, item in enumerate(files)
            if os.path.basename(item['path']) == cursor.get('file_name')
        ), None)
    if index is None:
        return None
    return index, int(cursor.get('byte_offset', 0))


def _has_more(files, start_index, start_offset, effective_cursor):
    position = _cursor_position(files, effective_cursor)
    if position is None:
        index, offset = start_index, start_offset
    else:
        index, offset = position
    for current_index in range(index, len(files)):
        current_offset = offset if current_index == index else 0
        try:
            if os.path.getsize(files[current_index]['path']) > current_offset:
                return True
        except OSError:
            return True
    return False


input_paths = inputs.get('input_paths')
input_path = inputs.get('input_path')
input_date = _date_str(inputs.get('input_date'))
explicit = bool(input_path) or bool(input_paths)
_batch_lease_fd = None
_batch_lease_token = ''
if not explicit:
    _batch_lease_fd, _batch_lease_token = _acquire_batch_lease()
try:
    batch_max_records = _positive_int(inputs.get('batch_max_records'), DEFAULT_BATCH_MAX_RECORDS)
    batch_max_bytes = _positive_int(inputs.get('batch_max_bytes'), DEFAULT_BATCH_MAX_BYTES)

    invalid_file_names = 0
    missing_files = 0
    cursor_revision = None
    requested_file_count = 0
    if explicit:
        files, requested_file_count, missing_files = _explicit_paths(input_paths, input_path)
        cursor_before = _normalise_cursor(inputs.get('resume_cursor'), explicit=True)
    else:
        files, invalid_file_names = _auto_paths(input_date)
        requested_file_count = len(files)
        cursor_before, cursor_revision = _load_production_cursor(_cursor_path(), input_date)

    start_index, start_offset, cursor_reset = _start_position(files, cursor_before, explicit)
    if not explicit and cursor_before is None and cursor_revision is not None:
        cursor_reset = True
    enriched_alerts = []
    loaded_files = []
    file_stats = []
    pending_cursor = None
    if cursor_reset and start_index < len(files):
        pending_cursor = _cursor_after(files[start_index], start_index, input_date, start_offset, explicit)
    resume_oversized_position = None if cursor_reset else _cursor_position(files, cursor_before)
    batch_bytes = 0
    oversized_bytes_discarded = 0
    stop_batch = False
    stats = {
        'candidate_file_count': len(files),
        'requested_file_count': requested_file_count,
        'touched_file_count': 0,
        'record_count': 0,
        'bytes_read': 0,
        'header_skipped': 0,
        'empty_lines': 0,
        'bad_lines': 0,
        'non_object_lines': 0,
        'oversized_lines': 0,
        'oversized_bytes_discarded': 0,
        'partial_lines': 0,
        'invalid_file_names': invalid_file_names,
        'missing_files': missing_files,
        'cursor_invalidated': cursor_reset,
        'has_more': False,
        'files': file_stats,
    }

    for file_index in range(start_index, len(files)):
        item = files[file_index]
        path = item['path']
        offset = start_offset if file_index == start_index else 0
        current = {
            'path': path,
            'records': 0,
            'bytes_read': 0,
            'headers': 0,
            'empty_lines': 0,
            'bad_lines': 0,
            'non_object_lines': 0,
            'oversized_lines': 0,
            'partial_lines': 0,
        }
        file_stats.append(current)
        loaded_files.append(path)
        resume_oversized = (
            file_index == start_index
            and cursor_before is not None
            and cursor_before.get('skipping_oversized_line') is True
            and resume_oversized_position == (file_index, offset)
        )
        try:
            with open(path, 'rb') as stream:
                if (
                    file_index == start_index
                    and offset > 0
                    and cursor_before is not None
                    and not cursor_reset
                    and not _cursor_matches_file(item, cursor_before, stream=stream)
                ):
                    offset = 0
                    cursor_reset = True
                    stats['cursor_invalidated'] = True
                    pending_cursor = _cursor_after(
                        item, file_index, input_date, 0, explicit, stream=stream
                    )
                    resume_oversized = False
                stream.seek(offset)
                if resume_oversized:
                    remaining = batch_max_bytes - batch_bytes
                    discard_status, discarded = _discard_to_newline(stream, remaining)
                    batch_bytes += discarded
                    current['bytes_read'] += discarded
                    oversized_bytes_discarded += discarded
                    if discarded:
                        pending_cursor = _cursor_after(
                            item,
                            file_index,
                            input_date,
                            stream.tell(),
                            explicit,
                            skipping_oversized_line=discard_status != 'line',
                            stream=stream,
                        )
                    if discard_status != 'line' or batch_bytes >= batch_max_bytes:
                        stop_batch = True

                while (
                    not stop_batch
                    and len(enriched_alerts) < batch_max_records
                    and batch_bytes < batch_max_bytes
                ):
                    line_start = stream.tell()
                    remaining = batch_max_bytes - batch_bytes
                    status, line, scanned = _read_bounded_line(stream, remaining)

                    if status == 'eof':
                        break
                    if status == 'partial':
                        batch_bytes += scanned
                        current['bytes_read'] += scanned
                        current['partial_lines'] += 1
                        stats['partial_lines'] += 1
                        stream.seek(line_start)
                        stop_batch = True
                        break
                    if status == 'limit':
                        batch_bytes += scanned
                        current['bytes_read'] += scanned
                        if batch_bytes > scanned:
                            stream.seek(line_start)
                            stop_batch = True
                            break

                        oversized_bytes_discarded += scanned
                        current['oversized_lines'] += 1
                        stats['oversized_lines'] += 1
                        pending_cursor = _cursor_after(
                            item,
                            file_index,
                            input_date,
                            stream.tell(),
                            explicit,
                            skipping_oversized_line=True,
                            stream=stream,
                        )
                        stop_batch = True
                        break

                    batch_bytes += scanned
                    current['bytes_read'] += scanned
                    pending_cursor = _cursor_after(
                        item, file_index, input_date, stream.tell(), explicit, stream=stream
                    )
                    payload = line[:-1]
                    if not payload.strip():
                        current['empty_lines'] += 1
                        stats['empty_lines'] += 1
                    else:
                        try:
                            obj = json.loads(payload.decode('utf-8'))
                        except Exception:
                            current['bad_lines'] += 1
                            stats['bad_lines'] += 1
                        else:
                            if not isinstance(obj, dict):
                                current['non_object_lines'] += 1
                                stats['non_object_lines'] += 1
                            elif obj.get('_type') == 'file_header':
                                current['headers'] += 1
                                stats['header_skipped'] += 1
                            else:
                                enriched_alerts.append(obj)
                                current['records'] += 1

                    if len(enriched_alerts) >= batch_max_records or batch_bytes >= batch_max_bytes:
                        stop_batch = True
                        break
        except Exception as exc:
            current['error'] = str(exc)
            print(f'[load] WARNING: failed to read {path!r}: {exc}')
            stop_batch = True

        if stop_batch:
            break

    effective_cursor = pending_cursor or cursor_before
    has_more = _has_more(files, start_index, start_offset, effective_cursor)
    stats['touched_file_count'] = len(loaded_files)
    stats['file_count'] = len(loaded_files)
    stats['record_count'] = len(enriched_alerts)
    stats['bytes_read'] = batch_bytes
    stats['oversized_bytes_discarded'] = oversized_bytes_discarded
    stats['has_more'] = has_more

    print(f'[load] DONE candidates={len(files)} touched={len(loaded_files)} '
          f'records={len(enriched_alerts)} bytes={batch_bytes} has_more={has_more}')

    outputs['enriched_alerts'] = enriched_alerts
    outputs['loaded_files'] = loaded_files
    outputs['load_stats'] = stats
    outputs['concurrency'] = _positive_int(inputs.get('concurrency'), 1)
    outputs['max_triage_cache_size'] = _positive_int(inputs.get('max_triage_cache_size'), 100000)
    outputs['input_date'] = input_date
    outputs['cursor_enabled'] = not explicit
    outputs['cursor_before'] = cursor_before
    outputs['cursor_revision'] = cursor_revision
    outputs['cursor_invalidated'] = cursor_reset
    outputs['pending_cursor'] = pending_cursor
    outputs['next_cursor'] = pending_cursor or cursor_before
    outputs['has_more'] = has_more
    outputs['batch_records'] = len(enriched_alerts)
    outputs['batch_bytes'] = batch_bytes
    outputs['_triage_persistence_succeeded'] = False
    outputs['_run_id'] = inputs.get('_run_id')
    outputs['triage_output_mode'] = inputs.get('triage_output_mode')
    outputs['persist_triage_output'] = inputs.get('persist_triage_output')
    outputs['soc_db_path'] = inputs.get('soc_db_path')
    outputs['jsonl_output_dir'] = inputs.get('jsonl_output_dir')

    outputs['_batch_lease_fd'] = _batch_lease_fd
    outputs['batch_lease_token'] = _batch_lease_token
except BaseException:
    _release_batch_lease(_batch_lease_fd)
    raise

"""Commit the production cursor after triage persistence succeeds."""

import datetime
import hashlib
import json
import os
import sys
import uuid

from flocks.config import Config


IS_WINDOWS = sys.platform == 'win32'
if IS_WINDOWS:
    import msvcrt  # noqa: F401
else:
    import fcntl   # noqa: F401

WORKFLOW_NAME = 'stream_alert_triage'


def _cursor_path():
    flocks_root = Config().get_global().data_dir.parent
    return flocks_root / 'workspace' / 'workflows' / WORKFLOW_NAME / '.triage_cursor.json'


class StaleCursorCommitError(RuntimeError):
    def __init__(self, current_cursor):
        super().__init__('stale_cursor_commit')
        self.current_cursor = current_cursor


def _cursor_revision(path):
    try:
        with open(path, 'rb') as stream:
            return hashlib.sha256(stream.read()).hexdigest()
    except FileNotFoundError:
        return None


def _read_current_cursor(path):
    try:
        with open(path, 'r', encoding='utf-8') as stream:
            value = json.load(stream)
    except Exception:
        return None
    return value if isinstance(value, dict) else None


def _acquire_cursor_lock(path):
    lock_path = path + '.lock'
    fh = open(lock_path, 'a+b')
    try:
        if IS_WINDOWS:
            if os.fstat(fh.fileno()).st_size == 0:
                fh.write(b'0')
                fh.flush()
            fh.seek(0)
            msvcrt.locking(fh.fileno(), msvcrt.LK_LOCK, 1)
        else:
            fcntl.flock(fh.fileno(), fcntl.LOCK_EX)
    except BaseException:
        fh.close()
        raise
    return fh


def _release_cursor_lock(fh):
    try:
        if IS_WINDOWS:
            try:
                fh.seek(0)
                msvcrt.locking(fh.fileno(), msvcrt.LK_UNLCK, 1)
            except OSError:
                pass
        else:
            fcntl.flock(fh.fileno(), fcntl.LOCK_UN)
    finally:
        fh.close()


def _release_batch_lease(fd):
    if type(fd) is not int or fd < 0:
        return
    try:
        if IS_WINDOWS:
            try:
                os.lseek(fd, 0, os.SEEK_SET)
                msvcrt.locking(fd, msvcrt.LK_UNLCK, 1)
            except OSError:
                pass
        else:
            fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)


def _cursor_is_monotonic(current, pending):
    if not isinstance(current, dict):
        return True
    current_date = str(current.get('date') or '')
    pending_date = str(pending.get('date') or '')
    if pending_date != current_date:
        return pending_date > current_date
    current_seq = int(current.get('file_seq', -1))
    pending_seq = int(pending.get('file_seq', -1))
    if pending_seq != current_seq:
        return pending_seq > current_seq
    if str(pending.get('file_name') or '') != str(current.get('file_name') or ''):
        return False
    return int(pending.get('byte_offset', -1)) >= int(current.get('byte_offset', -1))



def _cursor_reset_is_safe(current, pending):
    if not isinstance(current, dict):
        return True
    current_date = str(current.get('date') or '')
    pending_date = str(pending.get('date') or '')
    if pending_date != current_date:
        return pending_date > current_date
    try:
        current_seq = int(current.get('file_seq', -1))
        pending_seq = int(pending.get('file_seq', -1))
    except (TypeError, ValueError):
        return False
    if pending_seq != current_seq:
        return pending_seq > current_seq
    return str(pending.get('file_name') or '') == str(current.get('file_name') or '')


def _commit_cursor_atomic(
    path, pending_cursor, expected_revision=None, run_id=None, allow_reset=False
):
    path = os.fspath(path)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    lock_fh = _acquire_cursor_lock(path)
    try:
        current_revision = _cursor_revision(path)
        current_cursor = _read_current_cursor(path)
        position_is_valid = (
            _cursor_reset_is_safe(current_cursor, pending_cursor)
            if allow_reset
            else _cursor_is_monotonic(current_cursor, pending_cursor)
        )
        if current_revision != expected_revision or not position_is_valid:
            raise StaleCursorCommitError(current_cursor)

        committed = {
            'version': 2,
            'date': str(pending_cursor['date']),
            'file_seq': int(pending_cursor['file_seq']),
            'file_name': str(pending_cursor['file_name']),
            'byte_offset': int(pending_cursor['byte_offset']),
            'device_id': int(pending_cursor['device_id']),
            'file_id': int(pending_cursor['file_id']),
            'head_hash': str(pending_cursor['head_hash']),
            'boundary_start': int(pending_cursor['boundary_start']),
            'boundary_hash': str(pending_cursor['boundary_hash']),
            'updated_at': datetime.datetime.now().astimezone().isoformat(timespec='seconds'),
        }
        if pending_cursor.get('skipping_oversized_line') is True:
            committed['skipping_oversized_line'] = True

        token = str(run_id or uuid.uuid4().hex)
        safe_token = ''.join(char if char.isalnum() or char in '-_' else '_' for char in token)
        tmp_path = f'{path}.{safe_token}.{uuid.uuid4().hex}.tmp'
        try:
            with open(tmp_path, 'w', encoding='utf-8') as stream:
                json.dump(committed, stream, ensure_ascii=False, indent=2)
                stream.write(chr(10))
                stream.flush()
                os.fsync(stream.fileno())
            os.replace(tmp_path, path)
        except BaseException:
            try:
                if os.path.exists(tmp_path):
                    os.remove(tmp_path)
            except OSError:
                pass
            raise
        return committed
    finally:
        _release_cursor_lock(lock_fh)


